@startuml

class WebPortal {
  + VersionNumber : string
  + URLAddress : string
}

class Building {
  + ID : string
  + Name : string
  + EnergyClass : string
  + Address : string
  + YearOfConstruction : int
}

class AdditionalEntry {
  + Name : string
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + Value : float
  + Unit : string
}

class Image {
  + FileName : string
}

class User {
  + UserName : string
  + Email : string
  + Password : string
}

class Administrator extends User {
  + IDCardNumber : string
}

class Comment {
  + Content : string
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User : registered on
WebPortal "1" -- "*" Comment : viewed by

Building "1" -- "*" AdditionalEntry
Building "1" -- "*" Image
Building "1" -- "0..1" Image : profile photo

User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has

@enduml

